const health = $input.first().json;
const go = health && health.masterEnabled === true && String(health.orchestrationMode || '').toLowerCase() === 'n8n';
return [{ json: { go, reason: go ? null : 'master_or_mode', timestamp: new Date().toISOString() } }];

const config = $('GET Config').first().json;
const queueRes = $input.first().json;
const items = queueRes.items || [];
const QUEUE_CAP = 2;
if (items.length >= QUEUE_CAP) {
  return [{ json: { skipRun: true, reason: 'queue_cap', queueLength: items.length, timestamp: new Date().toISOString() } }];
}
const profileId = (config.enabledProfiles && config.enabledProfiles[0] && config.enabledProfiles[0].id) || '';
const comms = (config.communitiesByProfile || {})[profileId] || [];
const communityId = (comms[0] && comms[0].id) || '';
if (!profileId || !communityId) {
  return [{ json: { skipRun: true, reason: 'no_profile_or_community', timestamp: new Date().toISOString() } }];
}
return [{ json: { skipRun: false, profile_id: profileId, community_id: communityId, max_posts: 5, queueLength: items.length, timestamp: new Date().toISOString() } }];

const scan = $input.first().json;
const target = $('Queue Cap and Pick Target').first().json;
if (scan.error) {
  return [{ json: { error: scan.error, skipQueue: true, skipReason: scan.error, profile_id: target.profile_id, community_id: target.community_id, timestamp: new Date().toISOString() } }];
}
const posts = (scan.posts || []).filter(
  p => !p.already_commented && !p.blacklisted_match && (p.post_text || '').trim().length > 0
);
const config = $('GET Config').first().json;
const fallbackPrompt = (config.commentFallbackPrompt || '').trim() || 'Add value, be friendly and keep short.';
const first = posts[0];
if (!first) {
  return [{ json: { skipQueue: true, skipReason: 'no_eligible_posts', profile_id: target.profile_id, community_id: target.community_id, timestamp: new Date().toISOString() } }];
}
const keywordRules = config.keywordRules || [];
let keyword = 'general';
let keyword_rule_id = '';
let fallback_level_used = 'general_comment_fallback';
const text = (first.post_text || '').toLowerCase();
for (const rule of keywordRules) {
  if (!rule.active) continue;
  const k = (rule.keyword || '').toLowerCase();
  if (k && text.includes(k)) {
    keyword = rule.keyword;
    keyword_rule_id = rule.id || '';
    fallback_level_used = 'keyword_rule';
    break;
  }
}
return [{
  json: {
    profile_id: target.profile_id,
    community_id: target.community_id,
    post_url: first.post_url,
    post_id: first.post_id || first.post_url,
    post_text: (first.post_text || '').slice(0, 500),
    keyword,
    keyword_rule_id,
    prompt_used: fallbackPrompt,
    fallback_level_used,
    skipQueue: false,
    timestamp: new Date().toISOString()
  }
}];

const item = $input.first().json;
const scheduled = new Date(Date.now() + 60 * 1000);
const scheduled_for = scheduled.toISOString().replace(/\.\d{3}Z$/, 'Z');
return [{ json: { ...item, generated_comment: 'Nice point, that stood out to me too.', scheduled_for } }];

const res = $input.first().json;
const prev = $('Build Payload (Static Comment)').first().json;
return [{ json: { run: 'scan_and_queue', action: 'queued', queue_item_id: res.queue_item_id || res.id, profile_id: prev.profile_id, community_id: prev.community_id, post_url: prev.post_url, timestamp: new Date().toISOString() } }];
